/* ================================================================
 *   RENDU TEXTE BITMAP
 *   scale : 1=8x16, 2=16x32, 3=24x48, 4=32x64
 * ================================================================ */
static void drawChar(int cx, int cy, unsigned char c,
                     Uint8 r, Uint8 g, Uint8 b, int scale)
{
    if (c < 32 || c > 127) c = '?';
    const unsigned char *glyph = FONT8x16[c - 32];
    SDL_SetRenderDrawColor(gRen, r, g, b, 255);
    for (int row = 0; row < 16; row++) {
        unsigned char bits = glyph[row];
        /* Inverser les bits pour corriger le sens d affichage */
        unsigned char b2 = 0;
        b2 |= (unsigned char)((bits & 0x01) << 7);
        b2 |= (unsigned char)((bits & 0x02) << 5);
        b2 |= (unsigned char)((bits & 0x04) << 3);
        b2 |= (unsigned char)((bits & 0x08) << 1);
        b2 |= (unsigned char)((bits & 0x10) >> 1);
        b2 |= (unsigned char)((bits & 0x20) >> 3);
        b2 |= (unsigned char)((bits & 0x40) >> 5);
        b2 |= (unsigned char)((bits & 0x80) >> 7);
        for (int col = 0; col < 8; col++) {
            if (b2 & (0x80 >> col)) {
                SDL_Rect px = {
                    cx + col * scale,
                    cy + row * scale,
                    scale, scale
                };
                SDL_RenderFillRect(gRen, &px);
            }
        }
    }
}

/* Largeur en pixels d'une chaîne */
static int textW(const char *s, int scale) {
    return (int)strlen(s) * 8 * scale;
}

/* Hauteur d'une ligne */
static int textH(int scale) {
    return 16 * scale;
}

/* ── Helper SDL2_ttf: rendu texte Arial ── */
static void ttfRender(const char *txt, int x, int y, Uint8 R, Uint8 G, Uint8 B, int scale, int align) {
    if (!txt || !*txt) return;
    int fi = scale-1; if(fi<0)fi=0; if(fi>4)fi=4;
    if (!gFonts[fi]) return;
    SDL_Color col={R,G,B,255};
    SDL_Surface *s=TTF_RenderUTF8_Blended(gFonts[fi],txt,col);
    if(!s) return;
    SDL_Texture *t=SDL_CreateTextureFromSurface(gRen,s);
    if(!t){SDL_FreeSurface(s);return;}
    SDL_Rect d={0,y-s->h/2,s->w,s->h};
    if(align==0) d.x=x; else if(align==1) d.x=x-s->w/2; else d.x=x-s->w;
    SDL_FreeSurface(s);
    SDL_RenderCopy(gRen,t,NULL,&d);
    SDL_DestroyTexture(t);
}

/* Dessine texte centré horizontalement - SDL2_ttf Arial */
static void drawTextC(const char *s, int cy, Uint8 r, Uint8 g, Uint8 b, int scale) {
    ttfRender(s, WIN_W/2, cy, r, g, b, scale, 1);
}

/* Dessine texte aligné à gauche - SDL2_ttf Arial */
static void drawTextL(const char *s, int x, int cy, Uint8 r, Uint8 g, Uint8 b, int scale) {
    ttfRender(s, x, cy, r, g, b, scale, 0);
}

/* Dessine texte aligné à droite - SDL2_ttf Arial */
static void drawTextR(const char *s, int rx, int cy, Uint8 r, Uint8 g, Uint8 b, int scale) {
    ttfRender(s, rx, cy, r, g, b, scale, 2);
}

/* Convertit une chaîne UTF-8 simple en ASCII affichable
   (remplace les accents courants français) */
static void toAscii(const char *src, char *dst, int maxLen) {
    /* Table de remplacement : séquences UTF-8 -> remplacement ASCII */
    static const struct { const char *utf; const char *asc; } table[] = {
        {"\xc3\xa9","e"}, {"\xc3\xa8","e"}, {"\xc3\xaa","e"}, {"\xc3\xab","e"},
        {"\xc3\xa0","a"}, {"\xc3\xa2","a"}, {"\xc3\xa4","a"},
        {"\xc3\xb9","u"}, {"\xc3\xbb","u"}, {"\xc3\xbc","u"},
        {"\xc3\xb4","o"}, {"\xc3\xb6","o"},
        {"\xc3\xae","i"}, {"\xc3\xaf","i"},
        {"\xc3\xa7","c"},
        {"\xc3\x89","E"}, {"\xc3\x88","E"}, {"\xc3\x8a","E"},
        {"\xc3\x80","A"}, {"\xc3\x82","A"},
        {"\xc3\x99","U"}, {"\xc3\x9b","U"},
        {"\xc3\x94","O"},
        {"\xc3\x8e","I"},
        {"\xc3\x87","C"},
        {"\xe2\x80\x99","'"}, {"\xe2\x80\x98","'"},
        {"\xe2\x80\x93","-"}, {"\xe2\x80\x94","-"},
        {"\xe2\x80\xa6","..."}, {"\xc2\xab","<"}, {"\xc2\xbb",">"},
        {"\xe2\x98\x85","*"}, {"\xe2\x9c\x93","V"}, {"\xe2\x9c\x97","X"},
        {"\xe2\x8c\x82","!"}, {"\xe2\x86\x90","<"}, {"\xe2\x86\x92",">"},
        {"\xe2\x8c\x83","h"}, {"\xe2\x9c\x95","X"},
        {NULL, NULL}
    };
    int di = 0;
    int si = 0;
    int slen = (int)strlen(src);
    while (si < slen && di < maxLen - 1) {
        unsigned char c = (unsigned char)src[si];
        int replaced = 0;
        if (c >= 0x80) {
            for (int t = 0; table[t].utf; t++) {
                int tlen = (int)strlen(table[t].utf);
                if (si + tlen <= slen && memcmp(src+si, table[t].utf, tlen) == 0) {
                    /* Copier le(s) caractère(s) de remplacement */
                    const char *rep = table[t].asc;
                    while (*rep && di < maxLen - 1)
                        dst[di++] = *rep++;
                    si += tlen;
                    replaced = 1;
                    break;
                }
            }
            if (!replaced) {
                /* Ignorer l'octet multibyte inconnu */
                si++;
                while (si < slen && ((unsigned char)src[si] & 0xC0) == 0x80) si++;
            }
        } else {
            dst[di++] = (char)c;
            si++;
        }
    }
    dst[di] = '\0';
}

/* Découpe et dessine un texte en plusieurs lignes centrées */
static void drawWrapped(const char *raw, int cx, int startY, int maxW,
                        Uint8 r, Uint8 g, Uint8 b, int scale) {
    if (!raw || !*raw) return;
    int fi = scale-1; if(fi<0)fi=0; if(fi>4)fi=4;
    if (!gFonts[fi]) return;
    char buf[512]; toAscii(raw, buf, 512);
    SDL_Color col={r,g,b,255};
    SDL_Surface *s=TTF_RenderUTF8_Blended_Wrapped(gFonts[fi],buf,col,(Uint32)maxW);
    if(!s) return;
    SDL_Texture *t=SDL_CreateTextureFromSurface(gRen,s);
    if(!t){SDL_FreeSurface(s);return;}
    SDL_Rect d={cx-s->w/2,startY-s->h/2,s->w,s->h};
    SDL_FreeSurface(s);
    SDL_RenderCopy(gRen,t,NULL,&d);
    SDL_DestroyTexture(t);
}

/* ================================================================
 *   PRIMITIVES GRAPHIQUES
 * ================================================================ */
static void fillRect(int x, int y, int w, int h, Uint8 r, Uint8 g, Uint8 b, Uint8 a) {
    SDL_SetRenderDrawBlendMode(gRen, a < 255 ? SDL_BLENDMODE_BLEND : SDL_BLENDMODE_NONE);
    SDL_SetRenderDrawColor(gRen, r, g, b, a);
    SDL_Rect rc = {x, y, w, h};
    SDL_RenderFillRect(gRen, &rc);
}

static void drawRect(int x, int y, int w, int h, Uint8 r, Uint8 g, Uint8 b, int thick) {
    SDL_SetRenderDrawBlendMode(gRen, SDL_BLENDMODE_NONE);
    SDL_SetRenderDrawColor(gRen, r, g, b, 255);
    for (int i = 0; i < thick; i++) {
        SDL_Rect rc = {x+i, y+i, w-2*i, h-2*i};
        SDL_RenderDrawRect(gRen, &rc);
    }
}

static void drawLine(int x1, int y1, int x2, int y2, Uint8 r, Uint8 g, Uint8 b) {
    SDL_SetRenderDrawColor(gRen, r, g, b, 255);
    SDL_RenderDrawLine(gRen, x1, y1, x2, y2);
}

static void drawGradientBg(void) {
    for (int y = 0; y < WIN_H; y++) {
        float t = (float)y / WIN_H;
        Uint8 r = (Uint8)(8  + t * 6);
        Uint8 g = (Uint8)(10 + t * 8);
        Uint8 b = (Uint8)(28 + t * 22);
        SDL_SetRenderDrawColor(gRen, r, g, b, 255);
        SDL_RenderDrawLine(gRen, 0, y, WIN_W, y);
    }
}

/* Barre de progression */
static void drawProgressBar(int x, int y, int w, int h, float pct,
                            Uint8 br, Uint8 bg, Uint8 bb) {
    fillRect(x, y, w, h, 20, 20, 50, 200);
    drawRect(x, y, w, h, 0, 100, 180, 1);
    int fw = (int)(pct * (w-2));
    if (fw > 0) fillRect(x+1, y+1, fw, h-2, br, bg, bb, 255);
}

/* Étoiles animées */
static float gStarsX[150], gStarsY[150], gStarsBr[150];
static void initStars(void) {
    for (int i = 0; i < 150; i++) {
        gStarsX[i]  = (float)(rand() % WIN_W);
        gStarsY[i]  = (float)(rand() % WIN_H);
        gStarsBr[i] = 0.3f + (float)(rand()%70)/100.0f;
    }
}
static void drawStars(void) {
    for (int i = 0; i < 150; i++) {
        gStarsBr[i] += ((float)(rand()%11-5)) * 0.008f;
        if (gStarsBr[i] < 0.1f) gStarsBr[i] = 0.1f;
        if (gStarsBr[i] > 1.0f) gStarsBr[i] = 1.0f;
        Uint8 v = (Uint8)(gStarsBr[i] * 220);
        SDL_SetRenderDrawColor(gRen, v, v, (Uint8)(v < 200 ? v + 40 : 255), 255);
        SDL_Rect pr = {(int)gStarsX[i], (int)gStarsY[i], 2, 2};
        SDL_RenderFillRect(gRen, &pr);
    }
}


/* ── Conversion coords souris → coords logiques ── */
static void mouseToLogical(int raw_x, int raw_y, int *lx, int *ly) {
    float sx, sy;
    SDL_RenderGetScale(gRen, &sx, &sy);
    int vx, vy;
    SDL_RenderGetViewport(gRen, &(SDL_Rect){0,0,0,0});
    /* Utiliser SDL_RenderWindowToLogical - methode officielle */
    float fx, fy;
    SDL_RenderWindowToLogical(gRen, raw_x, raw_y, &fx, &fy);
    *lx = (int)fx;
    *ly = (int)fy;
}

/* Bouton — retourne 1 si la souris est dessus */
static int isHovered(int cx, int cy, int w, int h) {
    int mx_raw, my_raw; SDL_GetMouseState(&mx_raw, &my_raw);
    int mx, my; mouseToLogical(mx_raw, my_raw, &mx, &my);
    return mx >= cx-w/2 && mx <= cx+w/2 && my >= cy-h/2 && my <= cy+h/2;
}

/* Dessine un bouton et retourne 1 si survolé */
static int drawButton(const char *label, int cx, int cy, int w, int h,
                      Uint8 br, Uint8 bg, Uint8 bb, int textScale)
{
    int hov = isHovered(cx, cy, w, h);
    /* Fond */
    Uint8 fr = hov ? (Uint8)(br/3+10) : (Uint8)(br/6);
    Uint8 fg = hov ? (Uint8)(bg/3+10) : (Uint8)(bg/6);
    Uint8 fb = hov ? (Uint8)(bb/3+15) : (Uint8)(bb/6+5);
    fillRect(cx-w/2, cy-h/2, w, h, fr, fg, fb, 220);
    /* Bordure (épaisse si survolé) */
    drawRect(cx-w/2, cy-h/2, w, h, br, bg, bb, hov ? 3 : 2);
    /* Halo */
    if (hov) {
        SDL_SetRenderDrawBlendMode(gRen, SDL_BLENDMODE_ADD);
        for (int i = 1; i <= 6; i++) {
            SDL_SetRenderDrawColor(gRen, br, bg, bb, (Uint8)(20-i*2));
            SDL_Rect hr = {cx-w/2-i, cy-h/2-i, w+2*i, h+2*i};
            SDL_RenderDrawRect(gRen, &hr);
        }
        SDL_SetRenderDrawBlendMode(gRen, SDL_BLENDMODE_NONE);
    }
    /* Texte - SDL2_ttf Arial */
    Uint8 tr = hov ? 240 : br;
    Uint8 tg = hov ? 245 : bg;
    Uint8 tb = hov ? 255 : bb;
    char asc[256]; toAscii(label, asc, 256);
    ttfRender(asc, cx, cy, tr, tg, tb, textScale, 1);
    return hov;
}

