/* ================================================================
 *   UTILITAIRES JEU
 * ================================================================ */
static void myShuf(int *a, int n) {
    for (int i = n-1; i > 0; i--) {
        int j = rand() % (i+1);
        int t = a[i]; a[i] = a[j]; a[j] = t;
    }
}

static void buildOrder(int chapter) {
    free(gOrder);
    gChapter = chapter;
    if (chapter < NUM_CHAPTERS) {
        gOrderLen = Q_PER_CHAPTER;
        gTotal    = Q_PER_CHAPTER;
        gOrder    = (int*)malloc(Q_PER_CHAPTER * sizeof(int));
        int base  = chapter * Q_PER_CHAPTER;
        for (int i = 0; i < Q_PER_CHAPTER; i++) gOrder[i] = base + i;
        myShuf(gOrder, Q_PER_CHAPTER);
    } else {
        gOrderLen = EXAM_TOTAL;
        gTotal    = EXAM_TOTAL;
        int pool[500];
        int poolLen = TOTAL_Q;
        for (int i = 0; i < poolLen; i++) pool[i] = i;
        myShuf(pool, poolLen);
        gOrder = (int*)malloc(EXAM_TOTAL * sizeof(int));
        for (int i = 0; i < EXAM_TOTAL; i++) gOrder[i] = pool[i % poolLen];
    }
}

