/* ══════════════════════════════════════════════════
   SAUVEGARDE DE LA PROGRESSION
   Fichier: save.dat (texte simple)
   ══════════════════════════════════════════════════ */
static void saveProgress(void) {
    FILE *f = fopen("save.dat", "w");
    if (!f) return;
    fprintf(f, "unlocked=%d\n", gUnlocked);
    fprintf(f, "exam=%d\n", gExamUnlocked);
    fclose(f);
}

static void loadProgress(void) {
    FILE *f = fopen("save.dat", "r");
    if (!f) return; /* pas de sauvegarde = on commence au debut */
    char line[64];
    while (fgets(line, sizeof(line), f)) {
        int val;
        if (sscanf(line, "unlocked=%d", &val) == 1) {
            if (val >= 1 && val <= NUM_CHAPTERS) gUnlocked = val;
        }
        if (sscanf(line, "exam=%d", &val) == 1) {
            gExamUnlocked = (val == 1) ? 1 : 0;
        }
    }
    fclose(f);
}

