/* Utilitaires géométriques */
static void fillCircle(int cx, int cy, int r, Uint8 R, Uint8 G, Uint8 B) {
    for (int y = -r; y <= r; y++) {
        int dx = (int)sqrtf((float)(r*r - y*y));
        SDL_SetRenderDrawColor(gRen, R, G, B, 255);
        SDL_RenderDrawLine(gRen, cx-dx, cy+y, cx+dx, cy+y);
    }
}
static void drawCircleOutline(int cx, int cy, int r, int thick, Uint8 R, Uint8 G, Uint8 B) {
    for (int t = 0; t < thick; t++) {
        int rr = r - t;
        for (int a = 0; a < 360; a++) {
            float rad = a * 3.14159f / 180.f;
            int px = cx + (int)(rr * cosf(rad));
            int py = cy + (int)(rr * sinf(rad));
            SDL_SetRenderDrawColor(gRen, R, G, B, 255);
            SDL_RenderDrawPoint(gRen, px, py);
        }
    }
}
static void fillCircleOutline(int cx, int cy, int r, int thick, Uint8 R, Uint8 G, Uint8 B) {
    for (int t = 0; t < thick; t++)
        drawCircleOutline(cx, cy, r-t, 1, R, G, B);
}

/* Triangle quelconque rempli - points (x0,y0),(x1,y1),(x2,y2) */
static void fillTriangle(int x0,int y0,int x1,int y1,int x2,int y2,Uint8 R,Uint8 G,Uint8 B) {
    int minY = y0<y1?(y0<y2?y0:y2):(y1<y2?y1:y2);
    int maxY = y0>y1?(y0>y2?y0:y2):(y1>y2?y1:y2);
    SDL_SetRenderDrawColor(gRen, R, G, B, 255);
    for (int y = minY; y <= maxY; y++) {
        int xs[6]; int nc=0;
        int pts[3][4]={{x0,y0,x1,y1},{x1,y1,x2,y2},{x2,y2,x0,y0}};
        for(int e=0;e<3;e++){
            int ax=pts[e][0],ay=pts[e][1],bx=pts[e][2],by=pts[e][3];
            if((ay<=y&&by>y)||(by<=y&&ay>y)){
                xs[nc++]=ax+(bx-ax)*(y-ay)/(by-ay);
            }
        }
        if(nc>=2){ if(xs[0]>xs[1]){int t=xs[0];xs[0]=xs[1];xs[1]=t;} SDL_RenderDrawLine(gRen,xs[0],y,xs[1],y); }
    }
}

/* Octogone STOP */
static void fillOctogon(int cx, int cy, int r, Uint8 R, Uint8 G, Uint8 B) {
    float cut = r * 0.383f;
    int ri = r - (int)cut;
    for (int y = -r; y <= r; y++) {
        int ax = (int)(r - (abs(y) > ri ? (abs(y)-ri)*1.0f : 0));
        if(ax > r) ax = r;
        SDL_SetRenderDrawColor(gRen, R, G, B, 255);
        SDL_RenderDrawLine(gRen, cx-ax, cy+y, cx+ax, cy+y);
    }
}

/* Texte centré à l'intérieur d'un panneau (version simplifiée) */
static void drawSignText(const char *txt, int cx, int cy, Uint8 R, Uint8 G, Uint8 B, int scale) {
    ttfRender(txt, cx, cy, R, G, B, scale < 2 ? 1 : 2, 1);
}

/* ───────────────────────────────────────────────────
   drawPanneau : dessine le panneau numéro id
   cx,cy = centre ; size = rayon/demi-côté de base
   ─────────────────────────────────────────────────── */
static void drawPanneau(int id, int cx, int cy, int sz) {
    if (id < 0 || id >= 50 || !gPanneaux[id]) return;
    int dim = sz * 2;
    SDL_Rect dst = {cx - dim/2, cy - dim/2, dim, dim};
    SDL_RenderCopy(gRen, gPanneaux[id], NULL, &dst);
}

static void renderQuestion(void) {
    drawGradientBg();
    drawStars();

    Uint32 now   = SDL_GetTicks();
    int elapsed  = (int)((now - gPhaseStart) / 1000);
    int remain   = QUESTION_TIME - elapsed;
    if (remain < 0) remain = 0;

    const QCM *q = &ALL_Q[gOrder[gQIdx]];
    int correct  = q->ok;

    /* ── HUD ── */
    char scoreStr[64];
    snprintf(scoreStr, sizeof(scoreStr), "Score: %d/%d", gScore, gQIdx);
    drawTextL(scoreStr, 20, 20, 0, 180, 255, 1);

    char qnStr[64];
    snprintf(qnStr, sizeof(qnStr), "Question %d / %d", gQIdx+1, gTotal);
    drawTextC(qnStr, 20, 150, 150, 180, 1);

    char chapStr[64]; toAscii(CHAP_NAMES[gChapter < 10 ? gChapter : 10], chapStr, 64);
    drawTextR(chapStr, WIN_W - 20, 20, 80, 100, 120, 1);

    /* Barre progression */
    float prog = gTotal > 0 ? (float)gQIdx / gTotal : 0;
    Uint8 pr = (Uint8)(prog > 0.5f ? 255 : 0);
    Uint8 pg = (Uint8)(prog < 0.5f ? 255 : 255 - (prog-0.5f)*2*255);
    drawProgressBar(60, 36, WIN_W-120, 8, prog, pr, pg, 50);

    /* ── Panneau question : CH1 = panneau dessiné, autres = texte ── */
    int panneau_id = -1;
    if (q->q[0] == '[' && q->q[1] == 'P') {
        panneau_id = (q->q[2]-'0')*10 + (q->q[3]-'0');
    }

    if (panneau_id >= 0) {
        /* CH1 : afficher le panneau dessiné au centre-haut */
        /* Zone panneau - fond sombre avec cadre lumineux */
        fillRect(WIN_W/2 - 160, 48, 320, 280, 12, 16, 35, 240);
        drawRect(WIN_W/2 - 160, 48, 320, 280, 0, 140, 220, 2);
        /* Halo de fond */
        fillRect(WIN_W/2 - 100, 78, 200, 200, 20, 25, 55, 200);
        /* Dessiner le panneau centré */
        drawPanneau(panneau_id, WIN_W/2, 188, 80);
        /* Question textuelle sous le panneau */
        const char *qtext = q->q + 5; /* Sauter [Pxx] */
        fillRect(60, 338, WIN_W-120, 52, 10, 15, 40, 220);
        drawRect(60, 338, WIN_W-120, 52, 0, 120, 200, 2);
        drawWrapped(qtext, WIN_W/2, 364, WIN_W-140, 180, 220, 255, 2);
    } else {
        /* Autres chapitres : texte normal */
        fillRect(60, 52, WIN_W-120, 110, 15, 20, 50, 220);
        drawRect(60, 52, WIN_W-120, 110, 0, 140, 220, 2);
        drawWrapped(q->q, WIN_W/2, 107, WIN_W-140, 220, 230, 255, 2);
    }

    /* ── Chrono : cadre ET texte centrés au même endroit ── */
    char timeStr[16]; snprintf(timeStr, sizeof(timeStr), "%d s", remain);
    int chrono_cx = WIN_W / 2 - 160;  /* colonne gauche */
    int chrono_cy = WIN_H - 28;
    Uint8 tbr = remain <= 10 ? 220 : 0;
    Uint8 tbg = remain <= 10 ? 30  : 180;
    Uint8 tbb = remain <= 10 ? 30  : 255;
    fillRect(chrono_cx - 70, chrono_cy - 22, 140, 44, remain<=10?60:10, remain<=10?5:20, remain<=10?5:50, 220);
    drawRect(chrono_cx - 70, chrono_cy - 22, 140, 44, tbr, tbg, tbb, 3);
    ttfRender(timeStr, chrono_cx, chrono_cy, tbr, tbg, tbb, remain<=10 ? 3 : 2, 1);

    /* Flash rouge a 10s */
    if (remain <= 10 && !gAnswered) {
        float fp = 0.5f + 0.5f * sinf(now * 0.015f);
        SDL_SetRenderDrawBlendMode(gRen, SDL_BLENDMODE_BLEND);
        SDL_SetRenderDrawColor(gRen, 255, 0, 0, (Uint8)(35*fp));
        SDL_Rect full = {0, 0, WIN_W, WIN_H};
        SDL_RenderFillRect(gRen, &full);
        SDL_SetRenderDrawBlendMode(gRen, SDL_BLENDMODE_NONE);
    }

    /* ── 4 boutons réponses ── */
    int bw = (WIN_W - 100) / 2 - 8;
    int bh = panneau_id >= 0 ? 80 : 100;
    int bstart = panneau_id >= 0 ? 402 : 176;
    int bgap   = panneau_id >= 0 ? 94  : 114;
    int bx[4]  = {50, 50+bw+16, 50, 50+bw+16};
    int by_[4] = {bstart, bstart, bstart+bgap, bstart+bgap};
    char labs[4][4] = {"A","B","C","D"};

    for (int i = 0; i < 4; i++) {
        int rx = bx[i], ry = by_[i];

        /* Couleurs par défaut */
        Uint8 fr=15,fg=20,fb=50, br_=60,bg_=80,bb_=140;
        Uint8 tr_=220,tg_=230,tb_=255;

        if (gAnswered || remain == 0) {
            if (i == correct) {
                if (gBlinkOn) {
                    fr=0;fg=120;fb=50;
                    br_=0;bg_=230;bb_=100;
                    tr_=0;tg_=255;tb_=130;
                } else {
                    fr=0;fg=60;fb=30;
                    br_=0;bg_=180;bb_=80;
                    tr_=180;tg_=255;tb_=200;
                }
            } else if (gUserAnswer == i) {
                fr=70;fg=5;fb=10;
                br_=220;bg_=30;bb_=30;
                tr_=255;tg_=60;tb_=60;
            }
            /* Timeout: bleu sur bonne réponse */
            if (remain == 0 && !gAnswered && i == correct) {
                fr=10;fg=30;fb=80;
                br_=30;bg_=100;bb_=255;
                tr_=100;tg_=180;tb_=255;
            }
        } else {
            /* Survol */
            int mx_raw2,my_raw2; SDL_GetMouseState(&mx_raw2,&my_raw2);
            int mx,my; mouseToLogical(mx_raw2,my_raw2,&mx,&my);
            if (mx>=rx && mx<=rx+bw && my>=ry && my<=ry+bh) {
                fr=20;fg=40;fb=90;
                br_=0;bg_=180;bb_=255;
            }
        }

        fillRect(rx, ry, bw, bh, fr, fg, fb, 220);
        drawRect(rx, ry, bw, bh, br_, bg_, bb_, 2);

        /* Badge lettre */
        fillRect(rx+8, ry+8, 30, 30, 0, 80, 160, 200);
        drawRect(rx+8, ry+8, 30, 30, br_, bg_, bb_, 1);
        drawTextL(labs[i], rx+14, ry+23, br_, bg_, bb_, 1);

        /* Texte réponse */
        drawWrapped(q->c[i], rx + bw/2 + 15, ry + bh/2, bw - 55, tr_, tg_, tb_, 1);
    }

    /* Message résultat */
    if (gAnswered) {
        const char *msg = (gUserAnswer == correct) ? "V  BONNE REPONSE !" : "X  MAUVAISE REPONSE";
        Uint8 mr = (gUserAnswer==correct) ? 0   : 255;
        Uint8 mg = (gUserAnswer==correct) ? 230 : 50;
        Uint8 mb = (gUserAnswer==correct) ? 100 : 50;
        drawTextC(msg, WIN_H - 30, mr, mg, mb, 2);
    } else if (remain == 0) {
        drawTextC("TEMPS ECOULE !", WIN_H - 30, 30, 100, 255, 2);
    }

    /* Bouton quitter en bas, decale a droite du chrono */
    int hq = drawButton("X QUITTER TEST", WIN_W/2 + 160, WIN_H - 28, 200, 40, 200, 50, 50, 1);
    if (hq) gHovered = 98;

    /* Blink */
    if (now - gLastBlink > 400) {
        gBlinkOn  = !gBlinkOn;
        gLastBlink = now;
    }
}

/* ── FEEDBACK COULEUR (3 secondes) ── */
static void renderFeedback(void) {
    drawGradientBg();
    drawStars();

    const QCM *q = &ALL_Q[gOrder[gQIdx]];
    int correct  = q->ok;
    int good     = (gUserAnswer == correct);

    /* Fond coloré semi-transparent sur tout l'écran */
    SDL_SetRenderDrawBlendMode(gRen, SDL_BLENDMODE_BLEND);
    if (good) {
        SDL_SetRenderDrawColor(gRen, 0, 180, 60, 55);
    } else {
        SDL_SetRenderDrawColor(gRen, 200, 20, 20, 55);
    }
    SDL_Rect full = {0, 0, WIN_W, WIN_H};
    SDL_RenderFillRect(gRen, &full);
    SDL_SetRenderDrawBlendMode(gRen, SDL_BLENDMODE_NONE);

    /* HUD */
    char scoreStr[64];
    snprintf(scoreStr, sizeof(scoreStr), "Score: %d/%d", gScore, gQIdx+1);
    drawTextL(scoreStr, 20, 20, 0, 180, 255, 1);
    char qnStr[64];
    snprintf(qnStr, sizeof(qnStr), "Question %d / %d", gQIdx+1, gTotal);
    drawTextC(qnStr, 20, 150, 150, 180, 1);
    float prog = gTotal > 0 ? (float)(gQIdx+1) / gTotal : 0;
    Uint8 pr = (Uint8)(prog > 0.5f ? 255 : 0);
    Uint8 pg = (Uint8)(prog < 0.5f ? 255 : 255-(prog-0.5f)*2*255);
    drawProgressBar(60, 36, WIN_W-120, 8, prog, pr, pg, 50);

    /* Panneau question */
    {
        int fb_pid = -1;
        if (q->q[0]=='['&&q->q[1]=='P') fb_pid=(q->q[2]-'0')*10+(q->q[3]-'0');
        if (fb_pid >= 0) {
            fillRect(WIN_W/2-160, 48, 320, 280, 12, 16, 35, 240);
            drawRect(WIN_W/2-160, 48, 320, 280, 0, 140, 220, 2);
            fillRect(WIN_W/2-100, 78, 200, 200, 20, 25, 55, 200);
            drawPanneau(fb_pid, WIN_W/2, 188, 80);
            const char *qt = q->q + 5;
            fillRect(60, 338, WIN_W-120, 52, 10, 15, 40, 220);
            drawRect(60, 338, WIN_W-120, 52, 0, 120, 200, 2);
            drawWrapped(qt, WIN_W/2, 364, WIN_W-140, 180, 220, 255, 2);
        } else {
            fillRect(60, 52, WIN_W-120, 110, 15, 20, 50, 220);
            drawRect(60, 52, WIN_W-120, 110, 0, 140, 220, 2);
            drawWrapped(q->q, WIN_W/2, 107, WIN_W-140, 220, 230, 255, 2);
        }
    }

    /* 4 boutons avec couleurs vert/rouge */
    int bw = (WIN_W - 100) / 2 - 8;
    int bh = 100;
    int bx[4] = {50, 50+bw+16, 50, 50+bw+16};
    int by_[4] = {176, 176, 290, 290};
    char labs[4][4] = {"A","B","C","D"};

    for (int i = 0; i < 4; i++) {
        int rx = bx[i], ry = by_[i];
        Uint8 fr=15,fg=20,fb=50, br_=60,bg_=80,bb_=140;
        Uint8 tr_=220,tg_=230,tb_=255;

        if (i == correct) {
            /* Bonne réponse toujours en VERT */
            fr=0;  fg=100; fb=30;
            br_=0; bg_=220; bb_=70;
            tr_=0; tg_=255; tb_=100;
        } else if (i == gUserAnswer && !good) {
            /* Mauvaise réponse choisie en ROUGE */
            fr=90; fg=5;  fb=10;
            br_=240; bg_=30; bb_=30;
            tr_=255; tg_=60; tb_=60;
        }

        fillRect(rx, ry, bw, bh, fr, fg, fb, 220);
        drawRect(rx, ry, bw, bh, br_, bg_, bb_, good && i==correct ? 4 : 2);
        fillRect(rx+8, ry+8, 30, 30, 0, 80, 160, 200);
        drawRect(rx+8, ry+8, 30, 30, br_, bg_, bb_, 1);
        drawTextL(labs[i], rx+14, ry+23, br_, bg_, bb_, 1);
        drawWrapped(q->c[i], rx + bw/2 + 15, ry + bh/2, bw - 55, tr_, tg_, tb_, 1);
    }

    /* Grand message résultat */
    if (gUserAnswer == -1) {
        drawTextC("TEMPS ECOULE !", WIN_H - 110, 30, 120, 255, 3);
    } else if (good) {
        drawTextC("V  BONNE REPONSE !", WIN_H - 110, 0, 240, 80, 3);
    } else {
        drawTextC("X  MAUVAISE REPONSE", WIN_H - 110, 255, 40, 40, 3);
    }

    /* Compte à rebours */
    Uint32 now     = SDL_GetTicks();
    int elapsed    = (int)((now - gFeedbackStart) / 1000);
    int remain     = FEEDBACK_TIME - elapsed;
    if (remain < 0) remain = 0;
    char buf[16]; snprintf(buf, sizeof(buf), "%d", remain);
    drawTextC(buf, WIN_H - 60, 160, 160, 190, 2);
}

/* ── EXPLICATION (10 secondes, mauvaise reponse, chapitres) ── */
static void renderExplain(void) {
    drawGradientBg();
    drawStars();

    const QCM *q  = &ALL_Q[gOrder[gQIdx]];
    int correct   = q->ok;
    Uint32 now2   = SDL_GetTicks();
    int elapsed   = (int)((now2 - gExplainStart) / 1000);
    int remain    = EXPLAIN_TIME - elapsed;
    if (remain < 0) remain = 0;

    /* Bandeau mauvaise reponse */
    fillRect(40, 50, WIN_W - 80, 50, 100, 10, 10, 230);
    drawRect(40, 50, WIN_W - 80, 50, 255, 60, 60, 2);
    drawTextC("X  MAUVAISE REPONSE", 75, 255, 80, 80, 2);

    /* Bonne reponse */
    fillRect(40, 115, WIN_W - 80, 50, 0, 70, 20, 230);
    drawRect(40, 115, WIN_W - 80, 50, 0, 200, 80, 2);
    drawTextC("V  BONNE REPONSE :", 140, 0, 220, 80, 2);

    char ans[320];
    snprintf(ans, sizeof(ans), "%c)  %s", 'A' + correct, q->c[correct]);
    fillRect(40, 178, WIN_W - 80, 58, 0, 50, 15, 210);
    drawRect(40, 178, WIN_W - 80, 58, 0, 180, 60, 2);
    drawWrapped(ans, WIN_W / 2, 207, WIN_W - 120, 0, 255, 120, 2);

    /* Separateur */
    drawLine(80, 252, WIN_W - 80, 252, 60, 80, 120);

    /* Explication */
    drawTextC("POURQUOI ?", 275, 180, 200, 255, 2);
    if (q->expl) {
        drawWrapped(q->expl, WIN_W / 2, 336, WIN_W - 80, 200, 210, 255, 1);
    }

    /* Barre de progression */
    float prog = (float)remain / EXPLAIN_TIME;
    fillRect(40, WIN_H - 75, WIN_W - 80, 12, 20, 20, 50, 200);
    int bw2 = (int)((WIN_W - 80) * prog);
    if (bw2 > 0) fillRect(40, WIN_H - 75, bw2, 12, 255, 140, 0, 230);
    drawRect(40, WIN_H - 75, WIN_W - 80, 12, 80, 80, 120, 1);

    char buf[32];
    snprintf(buf, sizeof(buf), "Prochaine question dans %d s", remain);
    drawTextC(buf, WIN_H - 48, 140, 140, 170, 1);
    (void)now2;
}

/* ── ECRAN DEBLOCAGE CHAPITRE ── */
static void renderUnlock(void) {
    drawGradientBg();
    drawStars();

    /* Halo central */
    SDL_SetRenderDrawBlendMode(gRen, SDL_BLENDMODE_BLEND);
    for (int r = 200; r > 0; r -= 10) {
        Uint8 alpha = (Uint8)(80 - r*80/200);
        SDL_SetRenderDrawColor(gRen, 255, 200, 0, alpha);
        SDL_Rect rc = {WIN_W/2-r, WIN_H/2-r, r*2, r*2};
        SDL_RenderFillRect(gRen, &rc);
    }
    SDL_SetRenderDrawBlendMode(gRen, SDL_BLENDMODE_NONE);

    /* Etoiles decoratives */
    for (int i = 0; i < 3; i++) {
        int ex = WIN_W/2 - 120 + i*120;
        int ey = WIN_H/2 - 120;
        for (int t = 0; t < 8; t++) {
            float a = t * 3.14159f / 4;
            int r2 = (t%2==0) ? 28 : 12;
            SDL_SetRenderDrawColor(gRen, 255, 200, 0, 255);
            SDL_RenderDrawLine(gRen, ex, ey,
                ex + (int)(r2*cosf(a)), ey + (int)(r2*sinf(a)));
        }
        fillCircle(ex, ey, 8, 255, 220, 50);
    }

    drawTextC("BRAVO !", WIN_H/2 - 80, 255, 220, 0, 5);

    char msg1[64];
    if (gUnlockChap < NUM_CHAPTERS) {
        char chname[128];
        toAscii(CHAP_NAMES[gUnlockChap], chname, 128);
        snprintf(msg1, sizeof(msg1), "Chapitre %d debloque !", gUnlockChap + 1);
    } else {
        snprintf(msg1, sizeof(msg1), "Examen final debloque !");
    }
    drawTextC(msg1, WIN_H/2 + 20, 0, 220, 100, 2);
    drawTextC("Vous pouvez passer a l'etape suivante !", WIN_H/2 + 60, 180, 210, 255, 1);

    int hb = drawButton("CONTINUER >>", WIN_W/2, WIN_H/2 + 130, 300, 54, 0, 200, 80, 2);
    if (hb) gHovered = 500;
    else if (gHovered == 500) gHovered = -1;
}

