    fillRect(WIN_W/2 - 50, WIN_H/2 + 155, 100, 12, 200, 150, 0, 255);
    fillRect(WIN_W/2 - 10, WIN_H/2 + 80, 20, 60, 255, 230, 50, 255);

    int hb = drawButton("RETOUR AU MENU", WIN_W/2, WIN_H - 60, 320, 54, 0, 180, 255, 2);
    if (hb) gHovered = 600;
