/* ── REPOS ── */
static void renderRest(void) {
    /* La derniere question est index gTotal-1.
       Apres sa reponse, gQIdx n'est pas encore incremente (c'est fait dans la transition).
       On est en S_REST avec gQIdx == gTotal-1 = derniere question repondue.
       Dans ce cas, on ne montre PAS le decompte. */
    if (gQIdx >= gTotal - 1 && gAnswered) return;

    drawGradientBg();
    drawStars();
    Uint32 now   = SDL_GetTicks();
    int elapsed  = (int)((now - gRestStart) / 1000);
    int remain   = REST_TIME - elapsed;
    if (remain < 0) remain = 0;

    char buf[8]; snprintf(buf, sizeof(buf), "%d", remain);
    drawTextC("Prochaine question dans...", WIN_H/2 - 80, 120, 140, 160, 2);
    Uint8 ng = (Uint8)(130 + remain * 25);
    drawTextC(buf, WIN_H/2 + 20, 0, ng, 180, 5);
}

/* ── RÉSULTAT ── */
static void renderResult(void) {
    drawGradientBg();
    drawStars();

    float pct  = gTotal > 0 ? (float)gScore / gTotal : 0;
    int   pass = (gTotal == EXAM_TOTAL) ? (gScore >= 170) : (gScore >= MIN_PASS);

    drawTextC("RESULTATS", 55, 0, 180, 255, 3);
    drawLine(100, 90, WIN_W-100, 90, 0, 100, 180);

    char noteStr[32];
    snprintf(noteStr, sizeof(noteStr), "%d / %d", gScore, gTotal);
    Uint8 nr = pass ? 0   : 220;
    Uint8 ng = pass ? 230 : 30;
    Uint8 nb = pass ? 100 : 30;
    drawTextC(noteStr, 175, nr, ng, nb, 4);

    /* Mention */
    const char *mention;
    if (pct >= 0.95f)      mention = "EXCELLENT !";
    else if (pct >= 0.85f) mention = "TRES BIEN";
    else if (pct >= 0.75f) mention = "BIEN";
    else if (pct >= 0.60f) mention = "PASSABLE";
    else                   mention = "INSUFFISANT";
    drawTextC(mention, 250, nr, ng, nb, 2);

    /* Barre */
    int needed = (gTotal == EXAM_TOTAL) ? 170 : MIN_PASS;
    char minStr[64];
    snprintf(minStr, sizeof(minStr), "Minimum requis: %d / %d", needed, gTotal);
    drawProgressBar(100, 275, WIN_W-200, 18, pct, nr, ng, nb);

    if (pass) {
        drawTextC("Felicitations ! Vous avez reussi.", 320, 0, 200, 80, 2);
        if (gTotal != EXAM_TOTAL) {
            char unlockMsg[64];
            snprintf(unlockMsg, sizeof(unlockMsg), "Chapitre %d debloque !", gChapter + 2);
            drawTextC(unlockMsg, 350, 255, 200, 0, 1);
        }
    } else {
        drawTextC(minStr, 320, 200, 60, 60, 1);
        drawTextC("Vous devez recommencer.", 345, 220, 60, 60, 1);
    }

    /* Stats */
    char statsStr[128];
    snprintf(statsStr, sizeof(statsStr),
             "Bonnes: %d  Erreurs: %d  Taux: %.1f%%",
             gScore, gTotal - gScore, pct*100.0f);
    drawTextC(statsStr, 390, 100, 120, 140, 1);

    /* Boutons */
    int h1 = drawButton("RECOMMENCER", WIN_W/2 - 180, 450, 300, 56, 0, 180, 255, 2);
    int h2 = drawButton("MENU PRINCIPAL", WIN_W/2 + 180, 450, 300, 56, 150,150,150, 2);

    if (h1) gHovered = 200;
    else if (h2) gHovered = 201;
    else gHovered = -1;
}

/* ── CONFIRMATION QUITTER ── */
static void renderConfirm(void) {
    SDL_SetRenderDrawBlendMode(gRen, SDL_BLENDMODE_BLEND);
    SDL_SetRenderDrawColor(gRen, 0, 0, 0, 190);
    SDL_Rect full = {0,0,WIN_W,WIN_H};
    SDL_RenderFillRect(gRen, &full);
    SDL_SetRenderDrawBlendMode(gRen, SDL_BLENDMODE_NONE);

    int bx=WIN_W/2-240, by=WIN_H/2-90, bw2=480, bh2=180;
    fillRect(bx, by, bw2, bh2, 15, 18, 45, 250);
    drawRect(bx, by, bw2, bh2, 220, 50, 50, 3);

    drawTextC("Quitter le test en cours ?", WIN_H/2 - 50, 220, 230, 255, 2);
    drawTextC("Progression perdue.", WIN_H/2, 120, 130, 150, 1);

    int h1 = drawButton("OUI QUITTER", WIN_W/2 - 105, WIN_H/2 + 60, 190, 46, 220,50,50, 1);
    int h2 = drawButton("CONTINUER",   WIN_W/2 + 105, WIN_H/2 + 60, 190, 46, 0,200,80, 1);
    if (h1) gHovered = 300;
    else if (h2) gHovered = 301;
    else gHovered = -1;
}

/* ================================================================
 *   GESTION EVENTS
 * ================================================================ */
static void handleMenu(SDL_Event *e) {
    if (e->type != SDL_MOUSEBUTTONDOWN || e->button.button != SDL_BUTTON_LEFT) return;
    if (gHovered == 100) { gState = S_CHAPTER; gHovered = -1; }
    if (gHovered == 102) gState = S_QUIT;
}

static void handleChapter(SDL_Event *e) {
    if (e->type != SDL_MOUSEBUTTONDOWN || e->button.button != SDL_BUTTON_LEFT) return;
    if (gHovered >= 0 && gHovered < NUM_CHAPTERS && gHovered < gUnlocked) {
        buildOrder(gHovered);
        gQIdx=0; gScore=0;
        gPhaseStart = SDL_GetTicks();
        gState = S_COUNTDOWN;
        gHovered = -1;
    }
    /* Examen final débloqué */
    if (gHovered == 10 && gExamUnlocked) {
        buildOrder(NUM_CHAPTERS);
        gQIdx=0; gScore=0;
        gPhaseStart = SDL_GetTicks();
        gState = S_COUNTDOWN;
        gHovered = -1;
    }
    if (gHovered == 99) { gState = S_MENU; gHovered = -1; }
}

static void handleQuestion(SDL_Event *e) {
    Uint32 now  = SDL_GetTicks();
    int elapsed = (int)((now - gPhaseStart) / 1000);
    int remain  = QUESTION_TIME - elapsed;

    /* Timeout */
    if (remain <= 0 && !gAnswered) {
        gAnswered        = 1;
        gUserAnswer      = -1;
        gFeedbackStart   = now;
        gState           = S_FEEDBACK;
        return;
    }

    if (gAnswered) return; /* déjà répondu, transition gérée dans main loop */

    /* Quitter */
    if (e->type == SDL_MOUSEBUTTONDOWN && gHovered == 98) {
        gConfirmQuit = 1; return;
    }

    if (e->type != SDL_MOUSEBUTTONDOWN || e->button.button != SDL_BUTTON_LEFT) return;

    int bw = (WIN_W - 100) / 2 - 8;
    /* Detecter CH1 (panneau dessine) -> boutons plus bas */
    const char *qq = ALL_Q[gOrder[gQIdx]].q;
    int is_panneau = (qq[0]=='['&&qq[1]=='P');
    int bh     = is_panneau ? 80  : 100;
    int bstart = is_panneau ? 402 : 176;
    int bgap   = is_panneau ? 94  : 114;
    int bx[4]  = {50, 50+bw+16, 50, 50+bw+16};
    int by_[4] = {bstart, bstart, bstart+bgap, bstart+bgap};
    int mx, my; mouseToLogical(e->button.x, e->button.y, &mx, &my);

    for (int i = 0; i < 4; i++) {
        if (mx>=bx[i] && mx<=bx[i]+bw && my>=by_[i] && my<=by_[i]+bh) {
            gUserAnswer    = i;
            gAnswered      = 1;
            gFeedbackStart = now;
            if (i == ALL_Q[gOrder[gQIdx]].ok) gScore++;
            gState         = S_FEEDBACK;
            break;
        }
    }
}

static void handleResult(SDL_Event *e) {
    int pass = (gTotal == EXAM_TOTAL) ? (gScore >= 170) : (gScore >= MIN_PASS);

    /* Deblocage automatique au premier affichage du résultat positif */
    if (pass && gTotal != EXAM_TOTAL) {
        /* Débloquer le chapitre suivant */
        if (gChapter + 1 >= gUnlocked) {
            gUnlocked = gChapter + 2;
            if (gUnlocked > NUM_CHAPTERS) gUnlocked = NUM_CHAPTERS;
        }
        /* Débloquer l'examen UNIQUEMENT si le chapitre 10 (index 9) vient d'etre reussi */
        if (gChapter == NUM_CHAPTERS - 1 && !gExamUnlocked) {
            gExamUnlocked = 1;
        }
        saveProgress(); /* Sauvegarder immédiatement */
    }
    if (pass && gTotal == EXAM_TOTAL) {
        /* Victoire examen final */
        if (e->type == SDL_MOUSEBUTTONDOWN && e->button.button == SDL_BUTTON_LEFT) {
            if (gHovered == 201 || gHovered == 200) {
                gState = S_EXAMWIN;
                gHovered = -1;
            }
        }
        return;
    }

    if (e->type != SDL_MOUSEBUTTONDOWN || e->button.button != SDL_BUTTON_LEFT) return;

    if (gHovered == 200) {
        buildOrder(gChapter);
        gQIdx=0; gScore=0;
        gPhaseStart = SDL_GetTicks();
        gState = S_COUNTDOWN;
        gHovered = -1;
    }
    if (gHovered == 201) {
        if (pass) {
            /* Afficher écran de déblocage si nouveau chapitre débloqué */
            if (gTotal != EXAM_TOTAL && gChapter + 2 <= gUnlocked) {
                gUnlockChap = gChapter + 1;
                gShowUnlock = 1;
                gState = S_UNLOCK;
            } else {
                gState = S_MENU;
            }
        } else {
            gState = S_MENU;
        }
        gHovered = -1;
    }
}

static void handleUnlock(SDL_Event *e) {
    if (e->type != SDL_MOUSEBUTTONDOWN || e->button.button != SDL_BUTTON_LEFT) return;
    if (gHovered == 500) {
        gShowUnlock = 0;
        gState = S_CHAPTER;
        gHovered = -1;
    }
}

static void handleExamWin(SDL_Event *e) {
    if (e->type != SDL_MOUSEBUTTONDOWN || e->button.button != SDL_BUTTON_LEFT) return;
    if (gHovered == 600) {
        gState = S_MENU;
        gHovered = -1;
    }
}

static void handleConfirm(SDL_Event *e) {
    if (e->type != SDL_MOUSEBUTTONDOWN || e->button.button != SDL_BUTTON_LEFT) return;
    if (gHovered == 300) { gConfirmQuit=0; gState=S_MENU; gHovered=-1; }
    if (gHovered == 301) { gConfirmQuit=0; gHovered=-1; }
}

/* ================================================================
 *   MAIN
 * ================================================================ */
int main(int argc, char *argv[]) {
    (void)argc; (void)argv;
    srand((unsigned)time(NULL));

    if (SDL_Init(SDL_INIT_VIDEO | SDL_INIT_TIMER) < 0) {
        fprintf(stderr, "SDL_Init: %s\n", SDL_GetError());
        return 1;
    }
    if (TTF_Init() < 0) { fprintf(stderr,"TTF_Init: %s\n",TTF_GetError()); return 1; }
    { int fsz[5]={14,20,28,36,52};
      for(int fi=0;fi<5;fi++){
        gFonts[fi]=TTF_OpenFont("arial.ttf",fsz[fi]);
        if(!gFonts[fi]){fprintf(stderr,"Erreur arial.ttf: %s\n",TTF_GetError());return 1;}
      }
    }

    gWin = SDL_CreateWindow(
        "Auto-Ecole QCM - Permis B",
        SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
        WIN_W, WIN_H,
        SDL_WINDOW_SHOWN | SDL_WINDOW_RESIZABLE
    );
    if (!gWin) { fprintf(stderr, "Window: %s\n", SDL_GetError()); return 1; }

    gRen = SDL_CreateRenderer(gWin, -1,
                              SDL_RENDERER_ACCELERATED | SDL_RENDERER_PRESENTVSYNC);
    if (!gRen) { fprintf(stderr, "Renderer: %s\n", SDL_GetError()); return 1; }
    SDL_SetRenderDrawBlendMode(gRen, SDL_BLENDMODE_BLEND);

    /* Résolution logique fixe : tout se met à l'échelle automatiquement */
    SDL_RenderSetLogicalSize(gRen, WIN_W, WIN_H);

    /* Charger les panneaux depuis les donnees integrees */
    for (int pi = 0; pi < 50; pi++) {
        SDL_RWops *rw = SDL_RWFromConstMem(PDATA[pi], PSIZES[pi]);
        if (rw) {
            SDL_Surface *s = SDL_LoadBMP_RW(rw, 1);
            if (s) { gPanneaux[pi] = SDL_CreateTextureFromSurface(gRen, s); SDL_FreeSurface(s); }
        }
    }
    loadProgress();
    initStars();
    gPhaseStart = SDL_GetTicks();
    gLastBlink  = SDL_GetTicks();

    while (gState != S_QUIT) {

        /* ── Transition REST→QUESTION/RESULT ── */
        if (gState == S_REST) {
            Uint32 now  = SDL_GetTicks();
            int elapsed = (int)((now - gRestStart) / 1000);
            if (elapsed >= REST_TIME) {
                gQIdx++;
                if (gQIdx >= gTotal) {
                    gState = S_RESULT;
                } else {
                    gPhaseStart = now;
                    gAnswered   = 0;
                    gUserAnswer = -1;
                    gState      = S_QUESTION;
                }
            }
        }

        /* ── Timeout question (sans event) ── */
        if (gState == S_QUESTION && !gAnswered) {
            Uint32 now  = SDL_GetTicks();
            int remain  = QUESTION_TIME - (int)((now - gPhaseStart)/1000);
            if (remain <= 0) {
                gAnswered      = 1;
                gUserAnswer    = -1;
                gFeedbackStart = now;
                gState         = S_FEEDBACK;
            }
        }

        /* ── Transition FEEDBACK→EXPLAIN ou REST ── */
        if (gState == S_FEEDBACK) {
            Uint32 now  = SDL_GetTicks();
            if ((int)((now - gFeedbackStart) / 1000) >= FEEDBACK_TIME) {
                int correct  = ALL_Q[gOrder[gQIdx]].ok;
                int is_wrong = (gUserAnswer != correct);
                int is_chap  = (gTotal != EXAM_TOTAL);
                if (is_wrong && is_chap && ALL_Q[gOrder[gQIdx]].expl != NULL) {
                    gExplainStart = now;
                    gState        = S_EXPLAIN;
                } else {
                    gRestStart = now;
                    gState     = S_REST;
                }
            }
        }

        /* ── Transition EXPLAIN→REST apres EXPLAIN_TIME secondes ── */
        if (gState == S_EXPLAIN) {
            Uint32 now = SDL_GetTicks();
            if ((int)((now - gExplainStart) / 1000) >= EXPLAIN_TIME) {
                gRestStart = now;
                gState     = S_REST;
            }
        }

        /* ── Events ── */
        SDL_Event e;
        while (SDL_PollEvent(&e)) {
            if (e.type == SDL_QUIT) { gState = S_QUIT; break; }
            if (e.type == SDL_WINDOWEVENT &&
                (e.window.event == SDL_WINDOWEVENT_RESIZED ||
                 e.window.event == SDL_WINDOWEVENT_SIZE_CHANGED)) {
                SDL_RenderSetLogicalSize(gRen, WIN_W, WIN_H);
            }
            if (e.type == SDL_KEYDOWN && e.key.keysym.sym == SDLK_ESCAPE) {
                if (gState == S_QUESTION || gState == S_REST || gState == S_FEEDBACK || gState == S_EXPLAIN) gConfirmQuit = 1;
                if (gState == S_UNLOCK) { gState = S_CHAPTER; }
                if (gState == S_EXAMWIN) { gState = S_MENU; }
                else gState = S_MENU;
            }

            if (gConfirmQuit) { handleConfirm(&e); continue; }

            switch (gState) {
                case S_MENU:     handleMenu(&e);     break;
                case S_CHAPTER:  handleChapter(&e);  break;
                case S_QUESTION: handleQuestion(&e); break;
                case S_RESULT:   handleResult(&e);   break;
                case S_UNLOCK:   handleUnlock(&e);   break;
                case S_EXAMWIN:  handleExamWin(&e);  break;
                default: break;
            }
        }

        /* ── Rendu ── */
        SDL_SetRenderDrawColor(gRen, 8, 10, 28, 255);
        SDL_RenderClear(gRen);

        switch (gState) {
            case S_MENU:      renderMenu();      break;
            case S_CHAPTER:   renderChapter();   break;
            case S_COUNTDOWN: renderCountdown(); break;
            case S_QUESTION:  renderQuestion();  break;
            case S_FEEDBACK:  renderFeedback();  break;
            case S_EXPLAIN:   renderExplain();   break;
            case S_REST:      renderRest();      break;
            case S_RESULT:    renderResult();    break;
            case S_UNLOCK:    renderUnlock();    break;
            case S_EXAMWIN:   renderExamWin();   break;
            default: break;
        }

        if (gConfirmQuit) renderConfirm();

        SDL_RenderPresent(gRen);
        SDL_Delay(16);
    }

    saveProgress(); /* Sauvegarde finale */
    free(gOrder);
    SDL_DestroyRenderer(gRen);
    SDL_DestroyWindow(gWin);
    for(int pi=0;pi<50;pi++) if(gPanneaux[pi]) SDL_DestroyTexture(gPanneaux[pi]);
    for(int fi=0;fi<5;fi++) if(gFonts[fi]) TTF_CloseFont(gFonts[fi]);
    TTF_Quit();
    SDL_Quit();
    return 0;
}
